const listClients = `-- name: ListClients :many
SELECT id, client_id, client_secret_hash, name, description, redirect_uris, grant_types, scopes, require_pkce, access_token_ttl, refresh_token_ttl, authorization_code_ttl, status, created_at, updated_at FROM oidc.client
WHERE ($1::text IS NULL OR status = $1)
  AND ($2::text IS NULL
       OR client_id LIKE $2 OR name LIKE $2)
ORDER BY created_at DESC
LIMIT $4 OFFSET $3
`

type ListClientsParams struct {
	Status pgtype.Text `json:"status"`
	Search pgtype.Text `json:"search"`
	Offset int32       `json:"offset"`
	Limit  int32       `json:"limit"`
}

func (q *Queries) ListClients(ctx context.Context, arg ListClientsParams) ([]OidcClient, error) {
	rows, err := q.db.Query(ctx, listClients,
		arg.Status,
		arg.Search,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OidcClient{}
	for rows.Next() {
		var i OidcClient
		if err := rows.Scan(
			&i.ID,
			&i.ClientID,
			&i.ClientSecretHash,
			&i.Name,
			&i.Description,
			&i.RedirectUris,
			&i.GrantTypes,
			&i.Scopes,
			&i.RequirePkce,
			&i.AccessTokenTtl,
			&i.RefreshTokenTtl,
			&i.AuthorizationCodeTtl,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

