const retireActiveSigningKey = `-- name: RetireActiveSigningKey :exec
UPDATE oidc.signing_key
SET status = 'retired', retired_at = now()
WHERE status = 'active'
`

// 轮换第一步:把当前 active 密钥降级为 retired。
//
// 旧密钥**不删除** —— 已经发出的令牌还在用它签名,删掉会让存量令牌
// 立刻验签失败。它继续留在 JWKS 里直到被显式 revoke。
func (q *Queries) RetireActiveSigningKey(ctx context.Context) error {
	_, err := q.db.Exec(ctx, retireActiveSigningKey)
	return err
}

